  const size=el('input');size.type='number';size.min='8';size.max='180';size.step='1';size.setAttribute('aria-label','字号');size.onchange=()=>{const v=Number(size.value);if(Number.isFinite(v))changeObjects({fontSize:clamp(v,8,180)},'修改字号');};controls.size=size;
