  g=group();const arrange=el('select');arrange.setAttribute('aria-label','排列对象');for(const [v,l]of [['','排列'],['front','置于顶层'],['back','置于底层'],['left','左侧对齐'],['center','水平居中'],['right','右侧对齐'],['top','顶部对齐'],['middle','垂直居中'],['bottom','底部对齐']])arrange.append(new Option(l,v));arrange.onchange=()=>{arrangeObjects(arrange.value);arrange.value='';};g.append(arrange);g=group();g.append(button('创建受众版本',null,()=>hooks.onForkAudience?.()));g=group();controls.review=button('整稿检查',null,reviewDeck);g.append(controls.review);g=group();g.append(button('返回文案',null,()=>{finishText();hooks.onBack?.();}),button('高级设置',null,showAdvancedSettings));
