 function addObject(props){const pid=page()?.id;if(!pid)return;const o={id:uid(),x:150,y:160,w:240,h:140,rotation:0,opacity:1,custom:true,...props};state.selection=new Set([o.id]);commit(p=>p.pages.find(x=>x.id===pid).objects.push(o),'插入对象');canvas.focus({preventScroll:true});}
 async function insertFiles(files,kind='image'){if(!files.length)return;const pid=page()?.id;if(!pid)return;try{const assets=await hooks.onAssets(files,kind);if(!assets?.length)return;const objects=[];for(const a of assets){let ratio=1.6;try{ratio=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i.naturalWidth/i.naturalHeight);i.onerror=reject;i.src=a.src;});}catch{}const w=kind==='logo'?160:Math.min(500,400*ratio);objects.push({id:uid(),type:'image',src:a.src,assetId:a.id,name:a.name,kind,x:kind==='logo'?1050:200+objects.length*24,y:kind==='logo'?40:170+objects.length*24,w,h:Math.min(w/ratio,450),rotation:0,opacity:1,fit:'contain',custom:true});}state.selection=new Set(objects.map(x=>x.id));commit(p=>p.pages.find(x=>x.id===pid)?.objects.push(...objects),kind==='logo'?'插入 Logo':'插入图片');}catch(e){notice(e.message||'素材上传失败，请重试');}}
 function copy(){state.clipboard=clone(selected());if(state.clipboard.length)notice(`已复制 ${state.clipboard.length} 个对象，Ctrl+V 粘贴`);}
