 function go(delta){const ps=project().pages,i=ps.findIndex(p=>p.id===page()?.id);if(ps[i+delta])selectPage(ps[i+delta].id);}
 function renderLeft(){slidesTab.setAttribute('aria-pressed',String(state.left==='slides'));themesTab.setAttribute('aria-pressed',String(state.left==='themes'));left.classList.toggle('ed-theme-list',state.left==='themes');const key=JSON.stringify([state.left,project().themeId,project().pages.map(p=>[p.id,p.title,p.background,p.objects])]);if(leftContent.dataset.key===key){leftContent.querySelectorAll('.ed-slide').forEach(b=>b.setAttribute('aria-current',b.dataset.pageId===state.pageId?'page':'false'));return;}const scroll=leftContent.scrollTop;leftContent.dataset.key=key;leftContent.replaceChildren();
  if(state.left==='themes'){leftContent.append(el('p','ed-pane-note',`${getTemplates().length} 套精选风格 · 应用于整份 PPT`));const grid=el('div','ed-theme-grid');for(const theme of getTemplates()){const b=button(theme.name,null,()=>previewTheme(theme));b.className='ed-theme-card';const img=el('img');img.src=theme.cover;img.alt=theme.name;img.loading='lazy';b.prepend(img);b.setAttribute('aria-pressed',String(project().themeId===theme.id));grid.append(b);}leftContent.append(grid);return;}
  const actions=el('div','ed-slide-actions');actions.append(el('span','',`${project().pages.length} 页`),button('新增页面','plus',addSlide,true));leftContent.append(actions);
  project().pages.forEach((pg,index)=>{const item=el('div','ed-slide-item');item.draggable=true;item.dataset.pageId=pg.id;item.ondragstart=e=>{e.dataTransfer.setData('application/x-weppt-page',pg.id);e.dataTransfer.effectAllowed='move';};item.ondragover=e=>{if([...e.dataTransfer.types].includes('application/x-weppt-page'))e.preventDefault();};item.ondrop=e=>{const from=e.dataTransfer.getData('application/x-weppt-page');if(!from||from===pg.id)return;e.preventDefault();commit(p=>{const i=p.pages.findIndex(x=>x.id===from),j=p.pages.findIndex(x=>x.id===pg.id);if(i<0||j<0)return;const [m]=p.pages.splice(i,1);p.pages.splice(j,0,m);},'调整页面顺序');};
   const b=button(`第 ${index+1} 页：${pg.title}`,null,()=>selectPage(pg.id));b.className='ed-slide';b.dataset.testid='slide';b.dataset.pageId=pg.id;b.setAttribute('aria-current',pg.id===state.pageId?'page':'false');const mini=el('div','ed-mini');mini.innerHTML=renderMini(pg);b.replaceChildren(mini,el('span','ed-slide-caption',`${String(index+1).padStart(2,'0')}  ${pg.title||'未命名页面'}`));item.append(b);const tools=el('div','ed-slide-item-tools');tools.append(button('复制页面','copy',()=>duplicateSlide(pg.id),true),button('删除页面','trash',()=>removeSlide(pg.id),true));item.append(tools);leftContent.append(item);});leftContent.scrollTop=scroll;
 }
 function addSlide(){try{const pid=page()?.id,source={id:uid(),title:'新页面',body:'在这里写下这一页的内容',role:'content',variant:0,objects:[]},p=createInheritedPage(project(),source,{anchorPageId:pid})||layoutPage(source,project().themeId);state.pageId=p.id;state.selection.clear();commit(pr=>{const index=pr.pages.findIndex(x=>x.id===pid);pr.pages.splice(index+1,0,p);},'新增页面');}catch(error){notice(error.message);}}
