  d.actions.append(button('应用数据',null,()=>{try{const current=project()?.pages.find(p=>p.id===pid)?.objects.find(item=>item.id===o.id);if(project()?.id!==owner||JSON.stringify(current)!==before)throw Error('图表已发生变化，请重新打开数据编辑。');if(rows.some(r=>r.values.some(v=>!v.value.trim())))throw Error('请填写完整数值。');const updated=updateNativeChart(o,{categories:rows.map(r=>r.label.value),series:names.map((name,j)=>({name:name.value,values:rows.map(r=>Number(r.values[j].value))}))});commit(p=>{const pg=p.pages.find(p=>p.id===pid);pg.objects=pg.objects.map(item=>item.id===o.id?updated:item);delete pg.designSnapshot;},'修改图表数据');d.close();}catch(error){notice(error.message);}}));d.show();
