 function dialog(title){const modal=el('dialog','ed-dialog'),header=el('div','ed-dialog-heading'),content=el('div','ed-dialog-content'),actions=el('div','ed-dialog-actions'),close=()=>{modal.close();modal.remove();};header.append(el('h2','',title),button('关闭','close',close,true));actions.append(button('取消',null,close));modal.append(header,content,actions);modal.oncancel=()=>modal.remove();root.append(modal);return{content,actions,close,show:()=>modal.showModal()};}
