 const keydown=e=>{if(state.destroyed||!root.isConnected||presentation)return;if(e.key==='F5'){e.preventDefault();play();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&state.editing){e.preventDefault();finishText();return;}const editing=e.target.isContentEditable||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(editing){if(e.key==='Escape'&&state.editing){e.preventDefault();finishText();canvas.focus();}return;}if(root.querySelector('dialog[open]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&['z','y','c','d','a','s'].includes(e.key.toLowerCase())){e.preventDefault();const key=e.key.toLowerCase();if(key==='z'){e.shiftKey?hooks.redo?.():hooks.undo?.();render();}else if(key==='y'){hooks.redo?.();render();}else if(key==='c')copy();else if(key==='v')paste();else if(key==='d'){copy();paste();}else if(key==='a'){state.selection=new Set(page().objects.map(o=>o.id));renderSelection();renderControls();}else notice('文稿会自动保存。');return;}if(['Delete','Backspace'].includes(e.key)&&state.selection.size){e.preventDefault();deleteSelected();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&state.selection.size){e.preventDefault();const n=e.shiftKey?10:1;changeObjects(o=>({x:o.x+(e.key==='ArrowLeft'?-n:e.key==='ArrowRight'?n:0),y:o.y+(e.key==='ArrowUp'?-n:e.key==='ArrowDown'?n:0)}),'微调位置');}else if(e.key==='PageDown'){e.preventDefault();go(1);}else if(e.key==='PageUp'){e.preventDefault();go(-1);}else if(e.key==='Escape'){state.selection.clear();renderSelection();renderControls();}};
 const pasteEvent=e=>{if(presentation)return;if(e.target.isContentEditable||/INPUT|TEXTAREA/.test(e.target.tagName))return;const files=[...e.clipboardData?.files||[]].filter(f=>f.type.startsWith('image/'));if(files.length){e.preventDefault();insertFiles(files);}else if(state.clipboard.length){e.preventDefault();paste();}};
